const labels={prepare:'กำลังตรวจจำนวนข้อมูล',applications:'กำลังลบใบสมัครและข้อมูลเช็คอิน',assignments:'กำลังลบการมอบหมายเจ้าหน้าที่',audit:'กำลังลบประวัติของกิจกรรม',files:'กำลังลบไฟล์โปสเตอร์และลายเซ็นใน Storage',signal:'กำลังลบข้อมูลการอัปเดต',nested:'กำลังลบข้อมูลย่อยของกิจกรรม',finish:'กำลังตรวจสอบและปิดงานลบ'};
export function createPurgeRunner(client,eventId,confirmation,{active=()=>true,onState=()=>{},onError=()=>{}}={}){
 let running=false,disposed=false;
 return {async run(){if(running||disposed||!active())return;running=true;try{let state=await client.purgeEvent({action:'start',eventId,...confirmation});if(disposed||!active())return;onState(state);while(!state.done&&!disposed&&active()){state=await client.purgeEvent({action:'step',eventId});if(!disposed&&active())onState(state)}}catch(error){if(!disposed&&active())onError(error)}finally{running=false}},dispose(){disposed=true},get running(){return running}};
}
export async function openEventPurge(event,client,isCurrent=()=>true){
 const modal=document.querySelector('#modal'),body=document.querySelector('#modalBody');body.replaceChildren();delete modal.dataset.applicationId;
 const host=document.createElement('section');host.innerHTML='<h2>ลบกิจกรรมถาวร</h2><p data-name></p><div class="auth-announcement"><strong>กู้คืนจากถังขยะไม่ได้</strong>ลบข้อมูลกิจกรรม ใบสมัคร เช็คอิน ประวัติแก้ไข การมอบหมายเจ้าหน้าที่ และไฟล์โปสเตอร์และลายเซ็นที่ผูกกับกิจกรรมนี้จาก Firebase</div><p class="sub">บัญชีผู้ใช้และข้อมูลกิจกรรมอื่นยังอยู่ ระบบเก็บเพียงบันทึกผู้สั่งลบ เวลา และจำนวนรายการ โดยไม่เก็บข้อมูลผู้สมัครไว้ในบันทึกนี้</p><p class="sub">สำรองข้อมูลและการเก็บรักษาของ Firebase จะหมดอายุตามนโยบายเดิม ส่วนไฟล์ที่ผู้ใช้ดาวน์โหลดไว้ไม่สามารถลบจากเครื่องของผู้ใช้ได้</p><p role="status" aria-live="polite" data-progress>กำลังตรวจรายการที่จะลบ…</p><div data-scope></div><div data-controls></div>';host.querySelector('[data-name]').textContent=event.name;body.append(host);modal.showModal();const status=host.querySelector('[data-progress]'),scope=host.querySelector('[data-scope]'),controls=host.querySelector('[data-controls]');let runner,disposed=false;
 const active=()=>!disposed&&isCurrent()&&modal.open&&body.contains(host),cleanup=()=>{disposed=true;runner?.dispose();modal.removeEventListener('close',cleanup)};modal.addEventListener('close',cleanup);
 try{
  const preview=await client.purgeEvent({action:'preview',eventId:event.id});if(!active())return;
  if(preview.done){status.textContent='กิจกรรมนี้ถูกลบถาวรแล้ว';return}
  for(const [key,title] of [['applications','ใบสมัครและข้อมูลเช็คอิน'],['assignments','การมอบหมายเจ้าหน้าที่'],['audit','ประวัติของกิจกรรม'],['files','ไฟล์โปสเตอร์และลายเซ็น']]){const p=document.createElement('p');p.textContent=title+': '+(preview.counts?.[key]??'กำลังตรวจสอบ')+' รายการ';scope.append(p)}
  status.textContent=preview.inProgress?'งานลบเริ่มไปแล้ว ข้อมูลบางส่วนอาจถูกลบไปแล้ว กดดำเนินการต่อเพื่อให้เสร็จ':'ตรวจชื่อและรายการก่อนยืนยันลบถาวร';
  const form=document.createElement('form');form.innerHTML='<label>พิมพ์ชื่อกิจกรรมให้ตรงเพื่อยืนยัน<input name="eventName" required autocomplete="off"></label><label><input name="acknowledged" type="checkbox" required style="width:auto"> ฉันเข้าใจว่าจะลบข้อมูลของกิจกรรมนี้ถาวรและกู้คืนจากถังขยะไม่ได้</label><div class="event-delete-buttons"><button class="danger-outline" type="submit" disabled></button><button type="button">ปิดหน้าต่าง</button></div><p class="sub">เมื่อเริ่มแล้วจะกู้คืนไม่ได้ หากปิดหน้าหรือเน็ตหลุด ให้กลับมาที่ถังขยะแล้วกด “ดำเนินการลบต่อ”</p>';controls.append(form);const submit=form.querySelector('[type=submit]'),close=form.querySelector('[type=button]');submit.textContent=preview.inProgress?'ดำเนินการลบต่อ':'ยืนยันลบถาวรจาก Firebase';const check=()=>submit.disabled=runner?.running||form.elements.eventName.value!==preview.name||!form.elements.acknowledged.checked;form.oninput=check;close.onclick=()=>modal.close();
  runner=createPurgeRunner(client,event.id,{confirmation:'PURGE_EVENT',expectedName:preview.name,previewToken:preview.previewToken},{active,onState:state=>{status.textContent=state.done?'ลบข้อมูลกิจกรรมและไฟล์ใน Firebase เสร็จแล้ว':labels[state.phase]||'กำลังลบข้อมูล…';if(state.done){form.replaceChildren();const done=document.createElement('button');done.type='button';done.textContent='ปิด';done.onclick=()=>modal.close();form.append(done)}},onError:error=>{status.textContent=(error.message||'การเชื่อมต่อขัดข้อง')+' หากเริ่มลบแล้ว ข้อมูลบางส่วนอาจถูกลบไปแล้ว กรุณารอแล้วกดดำเนินการต่อ';submit.textContent='ดำเนินการลบต่อ'}});
  form.onsubmit=async e=>{e.preventDefault();if(form.elements.eventName.value!==preview.name||!form.elements.acknowledged.checked||runner.running)return;submit.disabled=true;form.elements.eventName.disabled=true;form.elements.acknowledged.disabled=true;await runner.run();if(active()&&form.contains(submit))submit.disabled=false};
 }catch(error){if(active())status.textContent=error.message||'ตรวจรายการไม่ได้ กรุณาปิดแล้วลองใหม่'}
}
